"use strict";(globalThis.webpackChunkgrc||=[]).push([[1066],{43790(e){e.exports=JSON.parse('{"citeKey":"fernandes2026gpuh5","slug":"fernandes-2026-gpuh5-9b21","title":"GPUH5: A GPU-first I/O Library for Scientific Data","authors":["J. Fernandes","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"I/O is a bottleneck in GPU-accelerated science, yet scientific data-format libraries run only on the host. A kernel cannot write where its data lives: it must exit and copy its array before HDF5 can run, so the write point becomes a kernel boundary. Systems that let a GPU initiate I/O give up the data model, emitting flat, untyped byte ranges. We present GPUH5, a GPU-first I/O library for persistent kernels. It keeps HDF5\'s hierarchical paths and chunked arrays, replacing the container format with a key-value store, so the host precomputes every chunk\'s key and an in-kernel write reduces to enqueuing a pointer, light enough that the producer holds 98.8% achieved occupancy. On a single-GPU Gray-Scott simulation writing 380 snapshots to NVMe, GPUH5 hides 96% of the I/O its synchronous twin exposes, finishing 1.9\xd7 faster than default HDF5.","hasAbstract":true,"lede":"We present GPUH5, a GPU-first I/O library for persistent kernels.","links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw111&sess=sess129"},"tags":["GPU I/O","HDF5","Scientific Data"],"_projectIds":[],"grcSelected":false,"status":"accepted","visibility":"public","projectIds":[],"memberAuthors":["logan-luke","sun-xian-he","kougkas-anthony"]}')}}]);